# Better approach: Find all rectangular frames (hollow rectangles)
def find_hollow_rectangles(grid):
    rows = len(grid)
    cols = len(grid[0])

    frames = []

    # Check every possible top-left corner
    for r1 in range(rows):
        for c1 in range(cols):
            # Try every possible size starting from this point
            for height in range(2, min(rows - r1 + 1, 10)):  # Limit search depth
                for width in range(2, min(cols - c1 + 1, 10)):
                    r2 = r1 + height - 1
                    c2 = c1 + width - 1

                    if grid[r1][c1] == 6:  # Skip background start
                        continue

                    # Check if this forms a valid hollow rectangle
                    color = grid[r1][c1]

                    # Check all perimeter cells have same color
                    perimeter_ok = True
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            if (r == r1 or r == r2 or c == c1 or c == c2):
                                if grid[r][c] != color:
                                    perimeter_ok = False
                                    break
                        if not perimeter_ok:
                            break

                    if not perimeter_ok:
                        continue

                    # Check there are interior pixels (height >= 2, width >= 2 means interior exists)
                    # For hollow frame: interior cells should NOT all be the same color
                    has_interior_cells = (height >= 3 and width >= 3)

                    if has_interior_cells:
                        # Count how many perimeter cells have this color
                        perimeter_count = 0
                        for r in range(r1, r2 + 1):
                            for c in range(c1, c2 + 1):
                                if (r == r1 or r == r2 or c == c1 or c == c2):
                                    if grid[r][c] == color:
                                        perimeter_count += 1

                        # A hollow rectangle should have most but not all perimeter as the frame color
                        # Actually let's just count interior area
                        interior_area = (width - 2) * (height - 2)

                        frames.append({
                            'color': color,
                            'bbox': (r1, c1, r2, c2),
                            'area': width * height,
                            'perimeter_color_count': perimeter_count,
                            'interior_cells': ((r1+1, c1+1), (r1+1, c2-1), (r2-1, c1+1), (r2-1, c2-1))
                        })

    return frames

print("\nDemo hollow rectangles:")
rects_demo = find_hollow_rectangles(demo_input)
for i, rect in enumerate(rects_demo):
    print(f"  Frame {i}: color={rect['color']}, bbox={rect['bbox']}, perimeter_color_count={rect['perimeter_color_count']}, area={rect['area']}")

def find_all_hollow_frames(grid):
    """Find ALL hollow rectangular frames."""
    rows = len(grid)
    cols = len(grid[0])
    background = max(Counter(cell for row in grid for cell in row).items(), key=lambda x: x[1])[0]

    all_frames = []

    for r1 in range(rows):
        for c1 in range(cols):
            if grid[r1][c1] == background:
                continue

            frame_color = grid[r1][c1]

            # Try expanding from this corner
            for r2 in range(r1 + 2, rows):
                for c2 in range(c1 + 2, cols):
                    top_ok = all(grid[r1][cc] == frame_color for cc in range(c1, c2+1))
                    bottom_ok = all(grid[r2][cc] == frame_color for cc in range(c1, c2+1))
                    left_ok = all(grid[rr][c1] == frame_color for rr in range(r1, r2+1))
                    right_ok = all(grid[rr][c2] == frame_color for rr in range(r1, r2+1))

                    if not (top_ok and bottom_ok and left_ok and right_ok):
                        continue

                    interior_cells = []
                    for rr in range(r1+1, r2):
                        for cc in range(c1+1, c2):
                            interior_cells.append((rr, cc))

                    if not interior_cells:
                        continue

                    interior_colors = [grid[rr][cc] for rr, cc in interior_cells]
                    if not any(color != frame_color for color in interior_colors):
                        continue

                    all_frames.append({
                        'color': frame_color,
                        'bbox': ((r1, c1), (r2, c2)),
                        'height': r2 - r1 + 1,
                        'width': c2 - c1 + 1,
                        'interior_cells': interior_cells,
                        'area': (r2 - r1 + 1) * (c2 - c1 + 1),
                        'interior_count': len(interior_cells),
                        'perimeter_cells': [
                            (r1, cc) for cc in range(c1, c2+1)
                        ] + [
                            (r2, cc) for cc in range(c1, c2+1)
                        ] + [
                            (rr, c1) for rr in range(r1+1, r2)
                        ] + [
                            (rr, c2) for rr in range(r1+1, r2)
                        ]
                    })

    return all_frames

print("Finding all hollow frames in task input...")
all_frames = find_all_hollow_frames(input_grid)
print(f"Found {len(all_frames)} hollow frames:")

for i, f in enumerate(sorted(all_frames, key=lambda x: -x['area'])):
    print(f"  {i}: color={f['color']}, bbox={f['bbox']}, area={f['area']}, interior={f['interior_count']} cells")

# Check for overlaps
print("Checking frame overlaps...")
sorted_frames = sorted(all_frames, key=lambda x: -x['area'])

overlaps = []
for i in range(len(sorted_frames)):
    for j in range(i+1, len(sorted_frames)):
        f1 = sorted_frames[i]
        f2 = sorted_frames[j]

        cells1 = set(f1['perimeter_cells'] + f1['interior_cells'])
        cells2 = set(f2['perimeter_cells'] + f2['interior_cells'])

        overlap = cells1 & cells2
        if overlap:
            overlaps.append((f1, f2, overlap))

if overlaps:
    print(f"Found {len(overlaps)} overlapping frame pairs:")
    for f1, f2, occ in overlaps[:5]:
        print(f"  color_{f1['color']} vs color_{f2['color']}: {len(occ)} overlapping cells")
else:
    print("No overlapping frames found!")

print("\nSorted frames by area (descending):")
for i, f in enumerate(sorted_frames):
    print(f"  {i}: color={f['color']:2d}, bbox={f['bbox']}, area={f['area']:2d}, interior={f['interior_count']} cells")

# Prepare JSON submission
output = {'action': 'submit', 'grid': output_grid}
print(json.dumps(output))

